import { randomBytes } from 'node:crypto'
import { env } from '@server/config/env'
import { type DbOrTx, db } from '@server/db/connection'
import { courseCertificates, courses } from '@server/db/schema/catalog'
import { courseCertificateSettings } from '@server/db/schema/learning'
import { now } from '@server/lib/clock'
import { notFound } from '@server/lib/errors'
import { fileUrl, getFile, storeGenerated } from '@server/services/files.service'
import { eq } from 'drizzle-orm'
import { renderCertificatePdf } from './pdf'

/** Certificates: issued once per enrolment (unique), PDF generated by a job or on first read. */

export const ISSUER = 'Department of Culture and Tourism – Abu Dhabi'

export type Certificate = typeof courseCertificates.$inferSelect

export function newSerial(at: Date = now()) {
  return `DCT-${at.getUTCFullYear()}-${randomBytes(5).toString('hex').toUpperCase()}`
}

export const shareUrl = (serial: string) => `${env.APP_URL}/certificates/${serial}`

/** Issues the certificate for an enrolment if missing. Returns the row (new or existing). */
export async function issueCertificate(
  tx: DbOrTx,
  input: { enrolmentId: string; userId: string; courseId: string; learnerName: string },
) {
  const [created] = await tx
    .insert(courseCertificates)
    .values({ ...input, serial: newSerial(), issuedAt: now() })
    .onConflictDoNothing({ target: courseCertificates.enrolmentId })
    .returning()
  if (created) return { certificate: created, created: true }
  const [existing] = await tx
    .select()
    .from(courseCertificates)
    .where(eq(courseCertificates.enrolmentId, input.enrolmentId))
  return { certificate: existing!, created: false }
}

/** Generates and stores the PDF once (idempotent); returns the stored file. */
export async function ensureCertificatePdf(certificateId: string, tx: DbOrTx = db) {
  const [cert] = await tx
    .select()
    .from(courseCertificates)
    .where(eq(courseCertificates.id, certificateId))
  if (!cert) throw notFound()
  if (cert.pdfKey) {
    const existing = await getFile(cert.pdfKey, tx)
    if (existing) return existing
  }
  const [course] = await tx.select().from(courses).where(eq(courses.id, cert.courseId))
  const [settings] = await tx
    .select()
    .from(courseCertificateSettings)
    .where(eq(courseCertificateSettings.courseId, cert.courseId))
  const bytes = await renderCertificatePdf({
    learnerName: cert.learnerName,
    courseTitle: course?.title.en ?? '',
    serial: cert.serial,
    issuedAt: cert.issuedAt,
    issuer: ISSUER,
    signatureName: settings?.signatureName,
    signatureTitle: settings?.signatureTitle,
    verifyUrl: shareUrl(cert.serial),
  })
  const file = await storeGenerated(
    bytes,
    {
      category: 'certificate',
      contentType: 'application/pdf',
      ext: '.pdf',
      ownerId: cert.userId,
      name: `certificate-${cert.serial}.pdf`,
    },
    tx,
  )
  await tx
    .update(courseCertificates)
    .set({ pdfKey: file.id })
    .where(eq(courseCertificates.id, cert.id))
  return file
}

/** `{ id, serial, issuedAt, pdfUrl }` for the certificate owner. */
export async function certificateRef(cert: Certificate, viewerId: string) {
  const file = await ensureCertificatePdf(cert.id)
  return {
    id: cert.id,
    serial: cert.serial,
    issuedAt: cert.issuedAt.toISOString(),
    pdfUrl: fileUrl(file, viewerId),
  }
}

/** Public check: name, course and date only (no e-mail or other personal data). */
export async function verifyCertificate(serial: string) {
  const [row] = await db
    .select({ cert: courseCertificates, title: courses.title })
    .from(courseCertificates)
    .innerJoin(courses, eq(courses.id, courseCertificates.courseId))
    .where(eq(courseCertificates.serial, serial))
  if (!row) throw notFound('No certificate with this serial')
  return {
    valid: true,
    learnerName: row.cert.learnerName,
    courseTitle: row.title,
    issuedAt: row.cert.issuedAt.toISOString(),
    issuer: ISSUER,
  }
}
